// ─── File: PaymentRaceDemo.java ───
// Runnable demo: two concurrent requests with the SAME key → one charge only.
package com.bank.paymentrace;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class PaymentRaceDemo {

    private static final Logger log = Logger.getLogger("PaymentRace");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        PaymentStore store = new PaymentStore();
        PaymentService service = new PaymentService(store);

        PaymentRequest req = new PaymentRequest("IDEM-RAJESH-77", "TXN-77",
                "SAV2001", new BigDecimal("50000"));

        // Simulate the RACE: client retry overlaps the original, fired concurrently.
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch gate = new CountDownLatch(1);
        Callable<String> attempt = () -> { gate.await(); return service.pay(req); };
        Future<String> a = pool.submit(attempt);
        Future<String> b = pool.submit(attempt);
        gate.countDown();   // release both at once

        log.info(() -> "RACE result A = " + get(a));
        log.info(() -> "RACE result B = " + get(b));
        log.info(() -> "Total charges applied for TXN-77 = " + store.chargeCount());

        // Payment-provider RETRY later with the same key → stored result, no charge.
        String retry = service.pay(req);
        log.info(() -> "PROVIDER retry = " + retry);
        log.info(() -> "Total charges after provider retry = " + store.chargeCount());

        pool.shutdown();
    }

    static String get(Future<String> f) {
        try { return f.get(); } catch (Exception e) { return "err:" + e; }
    }
}

