// ─── store/PaymentStore.java ───
// Models the DB: atomic key claim + UNIQUE(transactionId) + stored response.
class PaymentStore {
    enum State { IN_PROGRESS, DONE }
    private final ConcurrentHashMap<String, State> keyState = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> keyResponse = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Boolean> uniqueTxn = new ConcurrentHashMap<>();
    private final java.util.concurrent.atomic.AtomicInteger charges =
            new java.util.concurrent.atomic.AtomicInteger();

    // Atomic claim: returns true only for the FIRST caller of this key.
    boolean claimKey(String key) {
        return keyState.putIfAbsent(key, State.IN_PROGRESS) == null;
    }
    // Hard backstop: UNIQUE(transactionId). Returns false on duplicate.
    boolean insertUniqueTxn(String txnId) {
        return uniqueTxn.putIfAbsent(txnId, Boolean.TRUE) == null;
    }
    void recordCharge() { charges.incrementAndGet(); }
    void complete(String key, String response) {
        keyResponse.put(key, response);
        keyState.put(key, State.DONE);
    }
    State state(String key) { return keyState.get(key); }
    String response(String key) { return keyResponse.get(key); }
    int chargeCount() { return charges.get(); }
}

// ─── service/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger("PaymentRace");
    private final PaymentStore store;
    PaymentService(PaymentStore store) { this.store = store; }

    String pay(PaymentRequest req) {
        // Layer 1: atomic idempotency-key claim.
        if (!store.claimKey(req.idempotencyKey())) {
            // Someone else owns this key. If done, replay; else it's in progress.
            if (store.state(req.idempotencyKey()) == PaymentStore.State.DONE) {
                return store.response(req.idempotencyKey()) + " (replayed stored result)";
            }
            // In-progress: in real systems wait on the row lock or return 409.
            spinUntilDone(req.idempotencyKey());
            return store.response(req.idempotencyKey()) + " (replayed after wait)";
        }
        // Layer 2: hard DB backstop — UNIQUE(transactionId).
        if (!store.insertUniqueTxn(req.transactionId())) {
            String resp = "ALREADY PROCESSED (unique txn constraint)";
            store.complete(req.idempotencyKey(), resp);
            return resp;
        }
        // Layer 3: perform the charge inside the (simulated) transaction.
        store.recordCharge();
        String response = "CHARGED " + req.account() + " Rs." + req.amount()
                + " txn=" + req.transactionId();
        log.info(() -> "Performed charge for " + req.transactionId());
        // Layer 4: commit charge + stored response together.
        store.complete(req.idempotencyKey(), response);
        return response;
    }

    private void spinUntilDone(String key) {
        for (int i = 0; i < 100; i++) {
            if (store.state(key) == PaymentStore.State.DONE) return;
            try { Thread.sleep(5); } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); return;
            }
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
